<script setup>
import { rankedEntries, safeColour, tagLabels } from '../lib/career.js';
defineProps({ data:Object }); const emit=defineEmits(['add-profile','edit-profile','preview']);
</script>
<template><section class="view active"><div class="workspace-head"><div><p class="eyebrow">TAILORING RULES</p><h1>CV profiles</h1><p>Choose a focus and the evidence bank is ranked around it.</p></div><button class="primary" @click="emit('add-profile')">+ New profile</button></div><div class="profile-grid"><article v-for="profile in data.cvProfiles" :key="profile.id" class="profile-card" :style="{'--accent':safeColour(profile.accent)}"><div class="profile-accent"></div><div class="profile-card-head"><span class="profile-icon">{{ profile.name.slice(0,1) }}</span><button class="more" :aria-label="`Edit ${profile.name}`" @click="emit('edit-profile',profile.id)">•••</button></div><h2>{{ profile.name }}</h2><p>{{ profile.summary||'Define the audience and emphasis for this CV.' }}</p><div class="tag-row"><i v-for="tag in profile.tags||[]" :key="tag">{{ tagLabels[tag]||tag }}</i></div><footer><span>{{ rankedEntries(data.entries,profile).length }} relevant records</span><button @click="emit('preview',profile.id)">Preview →</button></footer></article></div></section></template>
